import { HttpErrorResponse } from '@angular/common/http';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { NgForm } from '@angular/forms';
import { Router } from '@angular/router';
import { element } from 'protractor';
import { threadId } from 'worker_threads';
import { interrogator } from '../../model/interrogator';
import { user } from '../../model/user';
import { UserService } from '../../services/user.service';

@Component({
  selector: 'app-users',
  templateUrl: './users.component.html',
  styleUrls: ['./users.component.scss']
})
export class UsersComponent implements OnInit {

  constructor(private userservice: UserService, private router: Router) { }

  @ViewChild("email") email: ElementRef;
  ngOnInit(): void { this.get_users() 
  
  }

  alertsDismiss: any = [];
  add_sucess(msg: string, type: string) {
    this.alertsDismiss.push({
      type: type,
      msg: msg,
      timeout: 2500
    });
  }
  
  public users: user[] = [ ];
  
  user: any;
  interrogator: interrogator;
  content: boolean;
  public users_fetch :user[];
  get_users() {
    this.users=[ ];
    this.userservice.get_all_users().subscribe(
      data => {
        if (data.status == 200) {
            this.users_fetch=data.body
            this.users_fetch.forEach(element =>
              {
                if (element.loginuser!=localStorage.getItem('current_user_id'))
                { 
                  this.users.push(element)
                }
              }
              )   
          this.content = true;
        }
        else if (data.status == 204) {
          this.content = false;
        }
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.userservice.clear();
          this.router.navigateByUrl('/login');
        }
      }
    )
  }

  get_interrogator(loginuser: string) {
    this.userservice.get_interrogator(loginuser).subscribe(
      data => {
        this.interrogator = data;
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.userservice.clear();
          this.router.navigateByUrl('/login');

        }
      }
    )
  }

  new_user: user;
  loginuser: any
  email_existe: boolean = false;
  loginuser_existe: boolean = false;
  result: any
  add(x: NgForm) {
    this.loginuser = localStorage.getItem('current_user_id');
    x.value.levelsecure="secure"
    this.userservice.save(this.loginuser, x.value).subscribe(
      (response) => {
        this.result = response.body.result
        if (this.result == "email existe") {
          this.email_existe = true;
          this.loginuser_existe = false;
        }
        else {
          if (this.result == "loginuser existe") {
            this.email_existe = false;
            this.loginuser_existe = true;
          }
          else 
          {
            if (this.result == "user saved successfully") {
              this.add_sucess(this.result,"primary")
              this.email_existe = false;
              this.loginuser_existe = false;
              this.hide();
              x.reset();
              this.get_users();
            }
          }
        }
        
      },
      (error: HttpErrorResponse) => {
        console.log(error)
        if (error.status == 403) {
          localStorage.clear();
          this.userservice.clear();
          this.router.navigateByUrl('/login');

        }
      }
    )
  }

  cancel_add(x: NgForm) {
    x.resetForm();
    this.email_existe = false;
    this.loginuser_existe = false;
  }


  hide() {
    let element: HTMLElement = document.getElementById('r') as HTMLElement;
    element.click();
  }
  hide2() {
    let element: HTMLElement = document.getElementById('r2') as HTMLElement;
    element.click();
  }

 interogator_update :interrogator;
 user_update :user;
 form_update:NgForm
 set(user :user)
  {
    this.user_update=user;
    this.userservice.get_interrogator(user.loginuser).subscribe(
      data => {
        this.interogator_update = data;

  
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.userservice.clear();
          this.router.navigateByUrl('/login');

        }
      }
    )

  }

cancel_update(y :NgForm , i :interrogator,u:user)
{
  y.setValue({"frominst":u.frominst,"levelsecure":u.levelsecure,"firstname":i.first_NAME_INTERROGATOR,
  "lastname":i.last_NAME_INTERROGATOR,"quality":i.quality});
}

  update(x:NgForm,y :user)
   {if (window.confirm('Are you sure')) {
x.value.loginuser=y.loginuser
  this.userservice.update(x.value).subscribe(
    data => {
      this.result = data.body.result
      this.add_sucess(data.body.result,"warning");
      this.get_users();
      this.hide2();

    },
    (error: HttpErrorResponse) => {
      if (error.status == 403) {
        localStorage.clear();
        this.userservice.clear();
        this.router.navigateByUrl('/login');
      }
    }
  )
}
  }

  public delete(loginuser : string)
  {  if (window.confirm('Are you sure')) {
    console.log(loginuser);
    this.userservice.delete(loginuser).subscribe(
      data => {
        this.result = data.body.result
        this.add_sucess(data.body.result,"danger");
        this.get_users();
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.userservice.clear();
          this.router.navigateByUrl('/login');
        }
      }
    )
  }
  }
}
